    const int dato = 4;
    if (dato < 0 || dato > 7) {
        std::cout << "Datos invalidos";
        return 0;
    }
    std::cout << "M+" << dato << "\n";
    const int resultado = conjunto(dato);
    std::cout << "M-" << dato << ":" << resultado;
    return 0;
}

