#include <iostream>

int triplicar(int dato) {
    std::cout << "T" << dato << "|";
    return dato * 3;
}

int evaluar(int dato) {
    if (dato == 0) {
        std::cout << "B0|";
        return 0;
    }
    const int base = dato + 1;
    std::cout << "E" << base << "|";
    const int recibido = triplicar(base);
    std::cout << "S" << base << ":" << recibido << "|";
    return base + recibido;
}

int main() {
    int dato{0};
    std::cin >> dato;
    if (dato < 0 || dato > 5) {
        std::cout << "Datos invalidos";
        return 0;
    }
    const int resultado = evaluar(dato);
    std::cout << "M" << dato << ":" << resultado;
    return 0;
}
